#!/usr/bin/env bash
# AgroMart — Live Prices page (লাইভ দাম), self-contained installer.
# Run from ~/Documents/AgroMart:  bash apply_liveprices.sh
set -euo pipefail
[ -d backend/src ] || { echo "ERROR: run from ~/Documents/AgroMart"; exit 1; }
say(){ echo "  $*"; }
mkdir -p backend/src/models backend/src/controllers backend/src/routes frontend/src/pages frontend/src/api seed

echo "==> [1/6] Writing new files..."
echo '' | base64 -d > 'backend/src/models/price.model.js' && say 'wrote backend/src/models/price.model.js'
echo '' | base64 -d > 'backend/src/controllers/prices.controller.js' && say 'wrote backend/src/controllers/prices.controller.js'
echo 'Ly8gcHJpY2VzLnJvdXRlcy5qcyDigJQgL2FwaS9wcmljZXMvKgppbXBvcnQgeyBSb3V0ZXIgfSBmcm9tICdleHByZXNzJzsKaW1wb3J0IHsgbGlzdFByaWNlcyB9IGZyb20gJy4uL2NvbnRyb2xsZXJzL3ByaWNlcy5jb250cm9sbGVyLmpzJzsKCmNvbnN0IHJvdXRlciA9IFJvdXRlcigpOwpyb3V0ZXIuZ2V0KCcvJywgbGlzdFByaWNlcyk7CmV4cG9ydCBkZWZhdWx0IHJvdXRlcjsK' | base64 -d > 'backend/src/routes/prices.routes.js' && say 'wrote backend/src/routes/prices.routes.js'
echo '' | base64 -d > 'frontend/src/api/prices.api.js' && say 'wrote frontend/src/api/prices.api.js'
echo '' | base64 -d > 'frontend/src/pages/LivePrices.jsx' && say 'wrote frontend/src/pages/LivePrices.jsx'
echo '' | base64 -d > 'seed/seed_price_history.sql' && say 'wrote seed/seed_price_history.sql'

echo "==> [2/6] Wiring backend/src/index.js..."
python3 - backend/src/index.js << 'PY'
import sys
f=sys.argv[1]; s=open(f).read()
if "prices.routes.js" not in s:
    s=s.replace(
        "import cropRoutes from './routes/crops.routes.js';",
        "import cropRoutes from './routes/crops.routes.js';\nimport priceRoutes from './routes/prices.routes.js';",
    )
    s=s.replace(
        "app.use('/api/crops', cropRoutes);",
        "app.use('/api/crops', cropRoutes);\napp.use('/api/prices', priceRoutes);",
    )
    open(f,'w').write(s); print("  wired index.js")
else:
    print("  already wired")
PY

echo "==> [3/6] Wiring frontend/src/App.jsx..."
python3 - frontend/src/App.jsx << 'PY'
import sys,re
f=sys.argv[1]; s=open(f).read()
if 'LivePrices' not in s:
    if "import Marketplace from './pages/Marketplace.jsx';" in s:
        s=s.replace("import Marketplace from './pages/Marketplace.jsx';",
                    "import Marketplace from './pages/Marketplace.jsx';\nimport LivePrices from './pages/LivePrices.jsx';")
    else:
        s=s.replace("import { LangProvider }","import LivePrices from './pages/LivePrices.jsx';\nimport { LangProvider }")
    s=re.sub(r"(\s*)</Routes>", r'\1  <Route path="/prices" element={<LivePrices/>} />\1</Routes>', s, count=1)
    open(f,'w').write(s); print("  wired App.jsx")
else: print("  already wired")
PY

echo "==> [4/6] Adding i18n keys..."
if grep -q "lp_title_buyer" frontend/src/i18n/strings.js; then say "keys already present (skip)"; else
python3 - frontend/src/i18n/strings.js << 'PY'
import sys
f=sys.argv[1]; s=open(f).read()
bn="""    lp_badge: 'রিয়েল-টাইম আপডেট',
    lp_title_buyer: 'লাইভ মার্কেট প্রাইস',
    lp_title_farmer: 'আজকের বাজার নির্দেশিকা',
    lp_sub_buyer: 'বাজার দরের চেয়ে সাশ্রয়ী মূল্যে সরাসরি কৃষকের কাছ থেকে কিনুন।',
    lp_sub_farmer: 'বাজার দর দেখে আপনার ফসলের সঠিক মূল্য নির্ধারণ করুন।',
    lp_view_buyer: 'ক্রেতা দৃশ্য',
    lp_view_farmer: 'কৃষক দৃশ্য',
    lp_search_ph: 'ফসলের নাম...',
    lp_agromart_price: 'AgroMart মূল্য',
    lp_agromart_band: 'AgroMart রেঞ্জ',
    lp_avg: 'গড়',
    lp_bazar_rate: 'বাজার দর',
    lp_listings: 'তালিকা',
    lp_save: 'সাশ্রয়',
    lp_gap_room: 'বেশি চাইতে পারেন',
    lp_order_now: 'অর্ডার করুন',
    lp_list_now: 'তালিকাভুক্ত করুন',
    lp_no_listings: 'কোনো তালিকা নেই',
    lp_error: 'ডেটা লোড করা যায়নি।',
    lp_empty: 'কোনো মূল্য তথ্য পাওয়া যায়নি।',
"""
en="""    lp_badge: 'Real-time update',
    lp_title_buyer: 'Live market prices',
    lp_title_farmer: "Today's market guide",
    lp_sub_buyer: 'Buy directly from farmers at prices below the bazar rate.',
    lp_sub_farmer: 'See bazar rates to price your crop competitively.',
    lp_view_buyer: 'Buyer view',
    lp_view_farmer: 'Farmer view',
    lp_search_ph: 'Crop name...',
    lp_agromart_price: 'AgroMart price',
    lp_agromart_band: 'AgroMart range',
    lp_avg: 'avg',
    lp_bazar_rate: 'Bazar rate',
    lp_listings: 'listings',
    lp_save: 'Save',
    lp_gap_room: 'Room to charge',
    lp_order_now: 'Order now',
    lp_list_now: 'List this crop',
    lp_no_listings: 'No listings',
    lp_error: 'Could not load data.',
    lp_empty: 'No price data available.',
"""
# insert after a known-existing anchor; try several
for anc in ["    how_cta_sub: 'একটি অ্যাকাউন্ট তৈরি করুন অথবা মার্কেটপ্লেস দেখুন।',\n",
            "    crop_added: 'ফসল যোগ হয়েছে!',\n",
            "    featured_see_all: 'সব দেখুন',\n"]:
    if anc in s: s=s.replace(anc, anc+bn, 1); break
for anc in ["    how_cta_sub: 'Create an account or browse the marketplace.',\n",
            "    crop_added: 'Crop added!',\n",
            "    featured_see_all: 'See all',\n"]:
    if anc in s: s=s.replace(anc, anc+en, 1); break
open(f,'w').write(s); print("  added i18n keys")
PY
fi

echo "==> [5/6] Seeding market_prices + 7-day price_history..."
if psql -U agromart -d agromart -h localhost -f seed/seed_price_history.sql >/tmp/lp_seed.log 2>&1; then
  say "seed applied — 9 crops with 7 days of history"
else
  say "seed failed — see /tmp/lp_seed.log. You can re-run: psql -U agromart -d agromart -h localhost -f seed/seed_price_history.sql"
fi

echo "==> [6/6] Done."
echo ""
echo "════ Live Prices applied. Restart backend, then: ════"
echo "  curl -s 'http://localhost:4000/api/prices?role=buyer' | head -c 200"
echo "  open http://localhost:5173/prices"
